import {planningSnapshot,compareDelivery} from './ribbon-delivery.js';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const labels={type:'סוג',parent:'קבוצה',order:'סדר',label:'שם',tooltip:'תיאור',command:'פקודה',iconHash:'אייקון'};
export function setupRibbonDelivery(getState){
 const launch=document.createElement('button');launch.className='ribbon-delivery-summary';launch.textContent='מצב הסרגל שבוצע';document.querySelector('#filters').before(launch);
 const dialog=document.createElement('dialog');dialog.className='cloud-sheet';dialog.id='ribbon-delivery-dialog';document.body.append(dialog);let generation=0,cache;
 function location(n,nodes){if(!n)return 'לא קיים בגרסה';const p=nodes.find(x=>x.id===n.parent);return (p?.label||(n.parent==='ribbon'?'סרגל':n.parent==='backlog'?'רעיונות':n.parent))+' · מקום '+(n.order+1);}
 function draw(){const state=getState(),d=state.ribbonDeployment;if(!d){dialog.innerHTML='<div class="sheet-head"><h2>הסרגל שבוצע</h2><button data-dismiss>✕</button></div><p>טרם התקבלה מסירת מבנה דרך הגשר. דוחות התיקונים הקיימים נשמרו; אין מהם הוכחה למיקום כפתורים בגרסה שנבנתה.</p><a href="RIBBON-DELIVERY.md" download>פורמט המסירה לקלוד · MD</a>';}
 else if(cache){const {snapshot,comparison}=cache;dialog.innerHTML=`<div class="sheet-head"><h2>הסרגל שבוצע · ${esc(d.packageVersion)}</h2><button data-dismiss>✕</button></div><p>לפי דיווח הבנייה של קלוד; אינו אישור התקנה או בדיקת Revit. מקור התכנון: גרסת ענן ${d.sourceRevision}.</p><p>${comparison.filter(x=>x.implemented).length} פריטים תואמים לתכנון הנוכחי. ${comparison.filter(x=>!x.implemented).length} פריטים עדיין שונים או אינם בגרסה.</p><details><summary>מבנה הגרסה שנמסרה</summary>${d.nodes.filter(n=>n.type==='panel').sort((a,b)=>a.order-b.order).map(p=>`<h3>${esc(p.label)}</h3>${tree(p.id,d.nodes)}`).join('')}</details><h3>השוואה לתכנון שלך</h3>${snapshot.nodes.map(n=>{const r=comparison.find(x=>x.id===n.id),actual=d.nodes.find(x=>x.id===n.id);return `<article class="repair-preview"><b>${esc(n.label)}</b><p>${r.implemented?'✓ הוטמע ב־'+esc(d.packageVersion):r.missing?'לא נכלל בגרסה שנמסרה':'ממתין להטמעה: '+r.different.map(k=>labels[k]).join(', ')}</p><p>בתכנון: ${esc(location(n,snapshot.nodes))}<br>בגרסה: ${esc(location(actual,d.nodes))}</p>${r.changedSincePull?'<small>התכנון הנוכחי השתנה מאז המשיכה של קלוד.</small>':''}</article>`}).join('')}${d.nodes.filter(n=>!snapshot.nodes.some(x=>x.id===n.id)).map(n=>`<article class="repair-preview"><b>${esc(n.label)}</b><p>קיים בגרסה בלבד; התכנון שלך לא שונה.</p></article>`).join('')}<details><summary>פרטי מסירה</summary><p dir="ltr">${esc(d.deliveryId)}<br>${esc(d.generatedAt)}<br>manifest SHA-256: ${esc(d.manifestSha256)}</p></details><a href="RIBBON-DELIVERY.md" download>פורמט המסירה לקלוד · MD</a>`;}
 dialog.querySelector('[data-dismiss]')?.addEventListener('click',()=>dialog.close());}
 function tree(parent,nodes){return '<ul>'+nodes.filter(n=>n.parent===parent).sort((a,b)=>a.order-b.order).map(n=>'<li>'+esc(n.label)+(nodes.some(x=>x.parent===n.id)?tree(n.id,nodes):'')+'</li>').join('')+'</ul>';}
 async function refresh(){const seq=++generation,state=getState(),d=state.ribbonDeployment;document.querySelectorAll('[data-delivery-badge]').forEach(x=>x.remove());if(!d){cache=null;launch.textContent='מצב הסרגל שבוצע · טרם התקבל מבנה';if(dialog.open)draw();return;}
 const snapshot=await planningSnapshot(structuredClone(state));if(seq!==generation)return;const comparison=compareDelivery(snapshot,d);cache={snapshot,comparison};launch.textContent='גרסה שבוצעה: '+d.packageVersion+' · '+comparison.filter(x=>x.implemented).length+' פריטים הוטמעו · השוואה ↗';for(const el of document.querySelectorAll('[data-edit]')){const r=comparison.find(x=>x.id===el.dataset.edit);if(!r||!el.classList.contains('card'))continue;const badge=document.createElement('small');badge.dataset.deliveryBadge='';badge.className='badge';badge.textContent=r.implemented?'✓ הוטמע ב־'+d.packageVersion:'ממתין להטמעה';el.append(badge);}if(dialog.open)draw();}
 launch.onclick=async()=>{await refresh();draw();dialog.showModal()};return {refresh};
}
